declare module "*.png" {
  const source: number;
  export default source;
}

declare module "*?raw" {
  const source: string;
  export default source;
}

declare module "*.jpg" {
  const source: number;
  export default source;
}

declare module "*.webp" {
  const source: number;
  export default source;
}

declare module "*.svg" {
  const source: number;
  export default source;
}
